cases.script:
builtin type -t clear
doc=$(help clear) || exit 90
case "$doc" in
  *"clear [-x] [-T TERM] | -V | --version | --help"*) printf 'help-synopsis-ok\n' ;;
  *) exit 91 ;;
esac

help_text=$(help clear)
case $help_text in
  *"-T TERM overrides the shell's TERM variable; -x keeps scrollback."*) ;;
  *) exit 92 ;;
esac
case $help_text in
  *"Writes control bytes to stdout, including when redirected; no newline."*) printf 'TERM and stdout clauses are present\n' ;;
  *) exit 93 ;;
esac
